import XCTest
@testable import NativeTestSeam
final class BoundedContinuationTests:XCTestCase {
  var controllers:[ObjectIdentifier:NativeController]=[:]
  func token()->GenerationToken{let c=NativeController(effects:LlmControllerJobTests.Effects(),permission:LlmControllerJobTests.Permission(),models:LlmControllerJobTests.Models());XCTAssertTrue(c.dispatch(.start));XCTAssertTrue(c.dispatch(.speechDetected,token:c.token));XCTAssertTrue(c.dispatch(.endpoint,token:c.token));let t=c.token!;controllers[ObjectIdentifier(t)]=c;return t}
  func policy(_ input:GenerationToken?=nil)throws->BoundedContinuation{let t=input ?? token();return try XCTUnwrap(BoundedContinuation.create(controller:controllers[ObjectIdentifier(t)]!,token:t,latest:"Requested longer answer.",requestedLonger:true,allowed:{!$0.cancelled}))}
  func create(latest:String,requested:Bool=false)->BoundedContinuation?{let t=token();return BoundedContinuation.create(controller:controllers[ObjectIdentifier(t)]!,token:t,latest:latest,requestedLonger:requested)}
  func testFakeLongStreamStopsAtFourBoundedChunks()throws{let p=try policy();for i in 0..<4{let chunk=try XCTUnwrap(p.next(count:{$0.utf8.count}));XCTAssertEqual(chunk.index,i+1);XCTAssertLessThanOrEqual(chunk.plan.promptTokens+chunk.plan.outputLimit,4096);XCTAssertEqual(chunk.plan.outputLimit,256);XCTAssertTrue(chunk.plan.text.contains("Requested longer answer."));let fakeTokens=(0..<256).map{_ in "w"};XCTAssertTrue(p.complete(chunk,text:fakeTokens.joined(separator:" "),generatedTokens:fakeTokens.count,approved:true))};XCTAssertEqual(p.totalGenerated,1024);XCTAssertNil(p.next(count:{$0.utf8.count}))}
  func testDefaultRequestAndApprovalDeny()throws{XCTAssertNil(create(latest:"Normal reply."));XCTAssertNil(create(latest:"Longer.",requested:true));let p=try policy();let chunk=try XCTUnwrap(p.next(count:{$0.utf8.count}));XCTAssertFalse(p.complete(chunk,text:"Unapproved.",generatedTokens:8));XCTAssertNil(p.next(count:{$0.utf8.count}))}
  func testOversizeDuplicateAndStaleCannotRevive()throws{let p=try policy();let c=try XCTUnwrap(p.next(count:{$0.utf8.count}));XCTAssertFalse(p.complete(c,text:"Too many.",generatedTokens:257,approved:true));XCTAssertNil(p.next(count:{$0.utf8.count}));let t=token(),stale=try policy(t);let old=try XCTUnwrap(stale.next(count:{$0.utf8.count}));_ = controllers[ObjectIdentifier(t)]!.stop();XCTAssertFalse(stale.complete(old,text:"Late.",generatedTokens:8,approved:true))
    let duplicate=try policy();let first=try XCTUnwrap(duplicate.next(count:{$0.utf8.count}));XCTAssertTrue(duplicate.complete(first,text:"Approved.",generatedTokens:8,approved:true));XCTAssertFalse(duplicate.complete(first,text:"Replay.",generatedTokens:8,approved:true));XCTAssertNil(duplicate.next(count:{$0.utf8.count}))
  }
  func testCancellationDuringBudgetAndIrreducibleContext()throws{let p=try policy();XCTAssertNil(p.next(count:{p.requestCancellation();return $0.utf8.count}));XCTAssertNil(p.next(count:{$0.utf8.count}));let ht=token();let huge=try XCTUnwrap(BoundedContinuation.create(controller:controllers[ObjectIdentifier(ht)]!,token:ht,latest:String(repeating:"x",count:4000),requestedLonger:true,allowed:{_ in true}));XCTAssertNil(huge.next(count:{$0.utf8.count}))}
  func testOnePolicyPerGenerationAndControllerStopRevokes()throws{let t=token(),c=controllers[ObjectIdentifier(t)]!;let p=try policy(t);XCTAssertNil(BoundedContinuation.create(controller:c,token:t,latest:"Reset.",requestedLonger:true,allowed:{_ in true}));let chunk=try XCTUnwrap(p.next(count:{$0.utf8.count}));_ = c.stop();XCTAssertFalse(p.complete(chunk,text:"Late.",generatedTokens:8,approved:true));XCTAssertNil(p.next(count:{$0.utf8.count}))}

}
